static void test_rows(void) { unsigned total=0U; TI_C54X_TEST_CHECK(sizeof(rows)/sizeof(rows[0])==20U); TI_C54X_TEST_CHECK(TI_C54X_OPCODE_ID_COUNT==261); for(size_t i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ const ti_c54x_opcode_metadata *m=ti_c54x_opcode_metadata_for_id(rows[i].id); TI_C54X_TEST_CHECK(m!=NULL); TI_C54X_TEST_CHECK(m->first_word_value==rows[i].value); TI_C54X_TEST_CHECK(m->first_word_mask==rows[i].mask); TI_C54X_TEST_CHECK(m->operand_layout==rows[i].layout); TI_C54X_TEST_CHECK(m->input_resources==rows[i].resources); TI_C54X_TEST_CHECK(m->program_word_count==rows[i].words); total+=rows[i].encodings;} TI_C54X_TEST_CHECK(total==240U); }
static void test_lookup(void) { unsigned populated=0U; for(uint32_t raw=0U;raw<=UINT16_MAX;++raw){ uint16_t w=(uint16_t)raw; ti_c54x_opcode_id id=ti_c54x_opcode_catalog_lookup_first_word(w); if(id!=TI_C54X_OPCODE_ID_UNKNOWN) ++populated; for(size_t i=0;i<sizeof(rows)/sizeof(rows[0]);++i) if(id==rows[i].id) TI_C54X_TEST_CHECK((uint16_t)(w&rows[i].mask)==rows[i].value); } TI_C54X_TEST_CHECK(populated==25617U); }
int main(void){ test_rows(); test_lookup(); return 0; }
